solution:
def conta_non_verificati(utilizzi):
    n = 0
    for u in utilizzi:
        if u > 1:
            n += 1
    return n

print(conta_non_verificati([0.8, 1.2, 1.05]))
print(conta_non_verificati([0.8, 1.2, 1.05]))
